/** Shared protocol source. Generated byte-for-byte into TaxiCRM; no Meta sender. */
export const protocol='2.0' as const;
export const sourceFields=['booking_id','customer_name','pickup_address','dropoff_address','pickup_time','driver_name','vehicle_registration','manage_booking_url','track_driver_url'] as const;
export type Source=typeof sourceFields[number];
export type IntentV2={schema_version:'2.0';mode:'DRY_RUN';origin:'operational_notification';workspace_id:string;booking_id:string;event_type:'booking.confirmed'|'driver.assigned';revision:number;recipient:string;idempotency_key:string;occurred_at:string;expires_at:string;rule:{id:string;version:number};content:{open_window_mode:'text'|'interactive';template:{id:string;name:string;language:string;fingerprint:string};body_mappings:{variable:string;source:Source}[];button_mappings:{index:number;source:'manage_booking_url'|'track_driver_url'}[]}};
export type GatewayState={conversation_id:string;conversation_revision:number;operator:boolean;last_eligible_inbound_at:string|null;recipient_verified:boolean;service_allowed:boolean;suppressed:boolean;provider_status:ProviderStatus;definitively_unavailable:boolean;seen:boolean;highest_booking_revision:number;capabilities:{text:boolean;named:boolean;dynamic_buttons:boolean;media:boolean;sms:boolean;parameter_sources:Source[]}};
export type ProviderStatus='NONE'|'ACCEPTED'|'DELIVERED'|'READ'|'REJECTED'|'FAILED'|'UNKNOWN';
export type ResultV2={schema_version:'2.0';mode:'DRY_RUN';idempotency_key:string;booking_id:string;rule:{id:string;version:number};conversation_id:string;conversation_revision:number;checked_at:string;result:'ready'|'omitted'|'blocked';reason:string;explanations?:string[];channel:'none'|'app'|'whatsapp'|'sms';content_mode?:'text'|'interactive'|'template'|'sms';rendered_text?:string;body_parameters?:{variable:string;source:Source;value:string}[];button_parameters?:{index:number;value:string}[];provider_status:ProviderStatus;provider_called:false};
const statuses=['NONE','ACCEPTED','DELIVERED','READ','REJECTED','FAILED','UNKNOWN'];
function object(x:unknown,keys:string[]):Record<string,unknown>{if(!x||typeof x!=='object'||Array.isArray(x)||Object.keys(x).some(k=>!keys.includes(k)))throw Error('INVALID_V2');return x as Record<string,unknown>}
function string(x:unknown,max=128):x is string{return typeof x==='string'&&x.length>0&&x.length<=max&&!/[\x00-\x1f]/.test(x)}
function revision(x:unknown):x is number{return Number.isSafeInteger(x)&&Number(x)>=0}
function date(x:unknown):x is string{return typeof x==='string'&&/^\d{4}-\d\d-\d\dT/.test(x)&&Number.isFinite(Date.parse(x))}
export function parseIntent(input:unknown,workspace:string):IntentV2{
 const x=object(input,['schema_version','mode','origin','workspace_id','booking_id','event_type','revision','recipient','idempotency_key','occurred_at','expires_at','rule','content']);
 if(x.schema_version!=='2.0'||x.mode!=='DRY_RUN'||x.origin!=='operational_notification')throw Error('INVALID_V2_MODE');
 if(x.workspace_id!==workspace)throw Error('WRONG_SCOPE');
 if(!string(x.booking_id)||!/^autocab:SYNTHETIC-[A-Za-z0-9_-]{1,80}$/.test(x.booking_id)||!['booking.confirmed','driver.assigned'].includes(String(x.event_type))||!revision(x.revision)||Number(x.revision)<1||typeof x.recipient!=='string'||!/^\+[1-9]\d{7,14}$/.test(x.recipient))throw Error('INVALID_V2_IDENTITY');
 if(x.idempotency_key!==`${x.booking_id}:${x.event_type}:${x.recipient}:${x.revision}`)throw Error('INVALID_IDEMPOTENCY_KEY');
 if(!date(x.occurred_at)||!date(x.expires_at)||Date.parse(x.expires_at)<=Date.parse(x.occurred_at)||Date.parse(x.expires_at)-Date.parse(x.occurred_at)>86400000)throw Error('INVALID_V2_EXPIRY');
 const r=object(x.rule,['id','version']);if(!string(r.id,80)||!revision(r.version)||Number(r.version)<1)throw Error('INVALID_V2_RULE');
 const c=object(x.content,['open_window_mode','template','body_mappings','button_mappings']);if(!['text','interactive'].includes(String(c.open_window_mode)))throw Error('INVALID_V2_CONTENT_MODE');
 const t=object(c.template,['id','name','language','fingerprint']);if(Object.keys(t).length!==4||Object.values(t).some(v=>!string(v,512)))throw Error('INVALID_V2_TEMPLATE');
 if(!Array.isArray(c.body_mappings)||c.body_mappings.length>20||!Array.isArray(c.button_mappings)||c.button_mappings.length>2)throw Error('INVALID_V2_MAPPING');
 const variables=new Set<string>(),slots=new Set<number>();for(const m of c.body_mappings){const v=object(m,['variable','source']);if(typeof v.variable!=='string'||!/^([1-9]\d*|[a-z_]+)$/.test(v.variable)||!sourceFields.includes(v.source as Source)||variables.has(v.variable))throw Error('INVALID_V2_MAPPING');variables.add(v.variable)}
 for(const m of c.button_mappings){const b=object(m,['index','source']);if(!revision(b.index)||Number(b.index)>9||slots.has(Number(b.index))||!['manage_booking_url','track_driver_url'].includes(String(b.source)))throw Error('INVALID_V2_MAPPING');slots.add(Number(b.index))}
 return x as unknown as IntentV2;
}
export function parseState(input:unknown):GatewayState{
 const x=object(input,['conversation_id','conversation_revision','operator','last_eligible_inbound_at','recipient_verified','service_allowed','suppressed','provider_status','definitively_unavailable','seen','highest_booking_revision','capabilities']);
 if(!string(x.conversation_id)||!revision(x.conversation_revision)||!revision(x.highest_booking_revision)||['operator','recipient_verified','service_allowed','suppressed','definitively_unavailable','seen'].some(k=>typeof x[k]!=='boolean')||!statuses.includes(String(x.provider_status))||(x.last_eligible_inbound_at!==null&&!date(x.last_eligible_inbound_at)))throw Error('INVALID_V2_GATEWAY_STATE');
 const c=object(x.capabilities,['text','named','dynamic_buttons','media','sms','parameter_sources']);if(['text','named','dynamic_buttons','media','sms'].some(k=>typeof c[k]!=='boolean')||!Array.isArray(c.parameter_sources)||c.parameter_sources.some(v=>!sourceFields.includes(v as Source)))throw Error('INVALID_V2_CAPABILITIES');return x as unknown as GatewayState;
}
export function parseResult(input:unknown,intent:IntentV2,state:GatewayState,now:number):ResultV2{
 const x=object(input,['schema_version','mode','idempotency_key','booking_id','rule','conversation_id','conversation_revision','checked_at','result','reason','explanations','channel','content_mode','rendered_text','body_parameters','button_parameters','provider_status','provider_called']);
 const r=object(x.rule,['id','version']);
 if(x.schema_version!=='2.0'||x.mode!=='DRY_RUN'||x.provider_called!==false||x.idempotency_key!==intent.idempotency_key||x.booking_id!==intent.booking_id||r.id!==intent.rule.id||r.version!==intent.rule.version||x.conversation_id!==state.conversation_id||x.conversation_revision!==state.conversation_revision)throw Error('V2_CORRELATION_CONFLICT');
 if(!date(x.checked_at)||Date.parse(x.checked_at)>now||now-Date.parse(x.checked_at)>30000)throw Error('STALE_V2_CONTEXT');
 if(!['ready','omitted','blocked'].includes(String(x.result))||!['none','app','whatsapp','sms'].includes(String(x.channel))||!string(x.reason)||!statuses.includes(String(x.provider_status))||x.provider_status!==state.provider_status)throw Error('INVALID_V2_RESULT');
 if(x.explanations!==undefined&&(!Array.isArray(x.explanations)||x.explanations.length>32||x.explanations.some(v=>!string(v,1024))))throw Error('INVALID_V2_RESULT');
 if(x.content_mode!==undefined&&!['text','interactive','template','sms'].includes(String(x.content_mode)))throw Error('INVALID_V2_RESULT');
 if(x.body_parameters!==undefined){if(!Array.isArray(x.body_parameters)||x.body_parameters.length>20)throw Error('INVALID_V2_RESULT');const variables=new Set<string>();for(const raw of x.body_parameters){const p=object(raw,['variable','source','value']);if(!string(p.variable)||variables.has(p.variable)||!sourceFields.includes(p.source as Source)||typeof p.value!=='string'||p.value.length>1024||/[\x00-\x1f]/.test(p.value))throw Error('INVALID_V2_RESULT');variables.add(p.variable)}}
 if(x.button_parameters!==undefined){if(!Array.isArray(x.button_parameters)||x.button_parameters.length>2)throw Error('INVALID_V2_RESULT');const slots=new Set<number>();for(const raw of x.button_parameters){const p=object(raw,['index','value']);if(!revision(p.index)||Number(p.index)>9||slots.has(Number(p.index))||!string(p.value,2048))throw Error('INVALID_V2_RESULT');try{const u=new URL(p.value);if(u.protocol!=='https:'||u.username||u.password)throw Error()}catch{throw Error('INVALID_V2_RESULT')}slots.add(Number(p.index))}}
 if(x.rendered_text!==undefined&&(typeof x.rendered_text!=='string'||x.rendered_text.length>4096))throw Error('INVALID_V2_RESULT');
 if(x.result==='ready'){
  if(!['whatsapp','sms'].includes(String(x.channel))||typeof x.rendered_text!=='string'||!x.rendered_text.trim())throw Error('INVALID_V2_RESULT');
  const open=state.last_eligible_inbound_at!==null&&Date.parse(state.last_eligible_inbound_at)<=now&&now-Date.parse(state.last_eligible_inbound_at)<86400000;
  if(x.channel==='whatsapp'&&((x.content_mode==='text'&&!open)||(x.content_mode==='template'&&open)||!['text','template'].includes(String(x.content_mode))))throw Error('INVALID_V2_CONTENT_SELECTION');
  if(x.channel==='sms'&&(!state.definitively_unavailable||state.provider_status==='UNKNOWN'||x.content_mode!=='sms'||String(x.rendered_text||'').length>1000))throw Error('INVALID_V2_SMS_FALLBACK');
  if(x.content_mode==='template'){
   if(!Array.isArray(x.body_parameters)||x.body_parameters.length!==intent.content.body_mappings.length||x.body_parameters.some(raw=>{const p=raw as {variable:string;source:Source};return !intent.content.body_mappings.some(m=>m.variable===p.variable&&m.source===p.source)}))throw Error('INVALID_V2_MAPPING');
   const buttons=Array.isArray(x.button_parameters)?x.button_parameters:[];if(buttons.length!==intent.content.button_mappings.length||buttons.some(raw=>!intent.content.button_mappings.some(b=>b.index===(raw as {index:number}).index)))throw Error('INVALID_V2_MAPPING');
  }else if(x.body_parameters!==undefined||x.button_parameters!==undefined)throw Error('INVALID_V2_CONTENT_SELECTION');
 }
 if(x.result!=='ready'&&(x.rendered_text!==undefined||x.body_parameters!==undefined||x.button_parameters!==undefined))throw Error('INVALID_V2_BLOCKED_CONTENT');
 return x as unknown as ResultV2;
}
/** Receipt provenance must already be verified by the existing Meta webhook receiver. */
export function applyReceipt(previous:{provider_message_id:string;state:ProviderStatus;revision:number},receipt:{provider_message_id:string;state:ProviderStatus;revision:number}){
 if(receipt.provider_message_id!==previous.provider_message_id)throw Error('V2_MESSAGE_CORRELATION_CONFLICT');
 if(!revision(receipt.revision)||!statuses.includes(receipt.state)||['NONE','UNKNOWN'].includes(receipt.state))throw Error('INVALID_V2_STATUS');
 if(receipt.revision<=previous.revision)return previous;
 const rank:Record<ProviderStatus,number>={NONE:0,UNKNOWN:0,ACCEPTED:1,REJECTED:2,FAILED:2,DELIVERED:3,READ:4};
 return rank[receipt.state]<rank[previous.state]?{...previous,revision:receipt.revision}:receipt;
}

export function stable(value:unknown):string{if(value===null||typeof value!=='object')return JSON.stringify(value);if(Array.isArray(value))return "["+value.map(stable).join(",")+"]";const o=value as Record<string,unknown>;return "{"+Object.keys(o).sort().map(k=>JSON.stringify(k)+":"+stable(o[k])).join(",")+"}"}
